// ──────────────────────────────────────────────────────────────────────
// ForEachChild (children in ast.json member order; the visitor returns
// true to stop, mirroring Go's Visitor; the method returns whether the
// traversal was stopped early)
// ──────────────────────────────────────────────────────────────────────

impl QualifiedName {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.left) {
            return true;
        }
        if visit(self.right) {
            return true;
        }
        false
    }
}

impl ComputedPropertyName {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.expression) {
            return true;
        }
        false
    }
}

impl Decorator {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.expression) {
            return true;
        }
        false
    }
}

impl IfStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.expression) {
            return true;
        }
        if visit(self.then_statement) {
            return true;
        }
        if let Some(id) = &self.else_statement {
            if visit(*id) {
                return true;
            }
        }
        false
    }
}

impl DoStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.statement) {
            return true;
        }
        if visit(self.expression) {
            return true;
        }
        false
    }
}

impl WhileStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.expression) {
            return true;
        }
        if visit(self.statement) {
            return true;
        }
        false
    }
}

impl ForStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if let Some(id) = &self.initializer {
            if visit(*id) {
                return true;
            }
        }
        if let Some(id) = &self.condition {
            if visit(*id) {
                return true;
            }
        }
        if let Some(id) = &self.incrementor {
            if visit(*id) {
                return true;
            }
        }
        if visit(self.statement) {
            return true;
        }
        false
    }
}

impl ForInOrOfStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if let Some(id) = &self.await_modifier {
            if visit(*id) {
                return true;
            }
        }
        if visit(self.initializer) {
            return true;
        }
        if visit(self.expression) {
            return true;
        }
        if visit(self.statement) {
            return true;
        }
        false
    }
}

impl BreakStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if let Some(id) = &self.label {
            if visit(*id) {
                return true;
            }
        }
        false
    }
}

impl ContinueStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if let Some(id) = &self.label {
            if visit(*id) {
                return true;
            }
        }
        false
    }
}

impl ReturnStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if let Some(id) = &self.expression {
            if visit(*id) {
                return true;
            }
        }
        false
    }
}

impl WithStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.expression) {
            return true;
        }
        if visit(self.statement) {
            return true;
        }
        false
    }
}

impl SwitchStatement {
    pub fn for_each_child(&self, visit: &mut dyn FnMut(NodeId) -> bool) -> bool {
        if visit(self.expression) {
            return true;
        }
        if visit(self.case_block) {
            return true;
        }
        false
    }
}

