    /// Go: `func (n *Node) ModifierFlags() ModifierFlags` (ast.go).
    pub fn modifier_flags(&self) -> ModifierFlags {
        self.modifiers().map_or(ModifierFlags::NONE, |m| m.modifier_flags)
    }

